import type {
  VariantAssignedWorkspace,
  WorkspaceContextAsset,
} from './contracts';
import type { ContextAssetPreviewKind } from './contextAssets';
import { VariantWorkspaceManager } from './VariantWorkspaceManager';
import { AgentVariantsError } from './errors';
import { createLogger } from '../utils/logger';

const log = createLogger('WorkspaceInventory');

type WorkspaceInventoryDeps = {
  worktreeManager: {
    getProjectCwdInWorktree(worktreePath: string): Promise<string>;
    cleanupSession(
      sessionId: string,
      freshDestinationParent?: string,
    ): Promise<void>;
  };
};

export interface WorktreeRecord {
  workItemId: string;
  worktreePath: string;
  diff?: string;
}

export interface StaticPreviewRecord {
  workItemId: string;
  briefId: string;
  entryPath: string;
  assetBase: string;
  hasAssets: boolean;
  assetFallbackBase?: string;
}

type SessionWorkspaceState = {
  worktrees: Map<string, WorktreeRecord>;
  staticPreviews: Map<string, StaticPreviewRecord>;
  workspaceManager: VariantWorkspaceManager;
  contextAssets: Map<string, WorkspaceContextAsset[]>;
  contextAssetPreviewKind?: ContextAssetPreviewKind;
  scaffoldBaseWorkItemId?: string;
  freshDestinationParent?: string;
  dependencyAbortController: AbortController;
  isCleanupStarted: boolean;
};

export class WorkspaceInventory {
  private readonly sessions = new Map<string, SessionWorkspaceState>();
  private readonly worktreeManager: WorkspaceInventoryDeps['worktreeManager'];

  constructor(deps: WorkspaceInventoryDeps) {
    this.worktreeManager = deps.worktreeManager;
  }

  openSession(sessionId: string): void {
    if (this.sessions.has(sessionId)) return;
    this.sessions.set(sessionId, {
      worktrees: new Map(),
      staticPreviews: new Map(),
      workspaceManager: new VariantWorkspaceManager(),
      contextAssets: new Map(),
      dependencyAbortController: new AbortController(),
      isCleanupStarted: false,
    });
  }

  hasSession(sessionId: string): boolean {
    return this.sessions.has(sessionId);
  }

  getWorktree(
    sessionId: string,
    workItemId: string,
  ): WorktreeRecord | undefined {
    return this.sessions.get(sessionId)?.worktrees.get(workItemId);
  }

  getWorktrees(sessionId: string): WorktreeRecord[] {
    return [...(this.sessions.get(sessionId)?.worktrees.values() ?? [])];
  }

  setWorktree(sessionId: string, record: WorktreeRecord): void {
    this.requireSession(sessionId).worktrees.set(record.workItemId, record);
  }

  async registerWorktree(
    sessionId: string,
    record: WorktreeRecord,
  ): Promise<void> {
    let projectPath = record.worktreePath;
    try {
      projectPath = await this.worktreeManager.getProjectCwdInWorktree(
        record.worktreePath,
      );
    } catch (error) {
      log.warn(
        `Failed to resolve project path in worktree ${record.worktreePath}; using its root`,
        error,
      );
    }
    this.setWorktree(sessionId, record);
    this.registerGitWorkspace({
      sessionId,
      workItemId: record.workItemId,
      rootPath: record.worktreePath,
      projectPath,
    });
  }

  getStaticPreview(
    sessionId: string,
    workItemId: string,
  ): StaticPreviewRecord | undefined {
    return this.sessions.get(sessionId)?.staticPreviews.get(workItemId);
  }

  getStaticPreviews(sessionId: string): StaticPreviewRecord[] {
    return [...(this.sessions.get(sessionId)?.staticPreviews.values() ?? [])];
  }

  setStaticPreview(sessionId: string, record: StaticPreviewRecord): void {
    this.requireSession(sessionId).staticPreviews.set(
      record.workItemId,
      record,
    );
  }

  registerGitWorkspace(args: {
    sessionId: string;
    workItemId: string;
    rootPath: string;
    projectPath: string;
  }): void {
    this.requireSession(args.sessionId).workspaceManager.registerGitWorkspace(
      args,
    );
  }

  assignArtifactWorkspace(args: {
    sessionId: string;
    workItemId: string;
    rootPath: string;
    allowedRoot: string;
    entryPath: string;
    sourceDirectory?: string;
    seedHtml?: string;
  }): void {
    this.requireSession(
      args.sessionId,
    ).workspaceManager.assignArtifactWorkspace(args);
  }

  getAssignedWorkspace(
    sessionId: string,
    workItemId: string,
  ): VariantAssignedWorkspace | undefined {
    return this.sessions
      .get(sessionId)
      ?.workspaceManager.getAssignedWorkspace(workItemId);
  }

  requireAssignedWorkspace(
    sessionId: string,
    workItemId: string,
    kind: 'static_preview' | 'refine_variant' | 'code_gen',
  ): VariantAssignedWorkspace {
    const workspace = this.getAssignedWorkspace(sessionId, workItemId);
    const expectedKind =
      kind === 'code_gen' ? 'git_worktree' : 'artifact_directory';
    if (!workspace || workspace.kind !== expectedKind) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Variant ${workItemId} has no assigned ${expectedKind} workspace`,
      );
    }
    return workspace;
  }

  readArtifact(
    sessionId: string,
    workItemId: string,
  ): {
    html: string;
    assetBase: string;
  } {
    return this.requireSession(sessionId).workspaceManager.readArtifact(
      workItemId,
    );
  }

  removeArtifactWorkspace(sessionId: string, workItemId: string): void {
    this.requireSession(sessionId).workspaceManager.removeArtifactWorkspace(
      workItemId,
    );
  }

  promoteArtifactWorkspace(args: {
    sessionId: string;
    sourceWorkItemId: string;
    targetWorkItemId: string;
  }): void {
    this.requireSession(
      args.sessionId,
    ).workspaceManager.promoteArtifactWorkspace({
      sourceWorkItemId: args.sourceWorkItemId,
      targetWorkItemId: args.targetWorkItemId,
    });
  }

  getContextAssets(
    sessionId: string,
    workItemId: string,
  ): WorkspaceContextAsset[] | undefined {
    return this.sessions.get(sessionId)?.contextAssets.get(workItemId);
  }

  setContextAssets(
    sessionId: string,
    workItemId: string,
    assets: WorkspaceContextAsset[],
  ): void {
    this.requireSession(sessionId).contextAssets.set(workItemId, assets);
  }

  getContextAssetPreviewKind(
    sessionId: string,
  ): ContextAssetPreviewKind | undefined {
    return this.sessions.get(sessionId)?.contextAssetPreviewKind;
  }

  setContextAssetPreviewKind(
    sessionId: string,
    previewKind: ContextAssetPreviewKind,
  ): void {
    this.requireSession(sessionId).contextAssetPreviewKind = previewKind;
  }

  setScaffoldBaseWorkItemId(sessionId: string, workItemId: string): void {
    this.requireSession(sessionId).scaffoldBaseWorkItemId = workItemId;
  }

  isScaffoldBaseWorkItem(sessionId: string, workItemId: string): boolean {
    return this.sessions.get(sessionId)?.scaffoldBaseWorkItemId === workItemId;
  }

  setFreshDestinationParent(
    sessionId: string,
    destinationParent: string,
  ): void {
    this.requireSession(sessionId).freshDestinationParent = destinationParent;
  }

  getDependencySignal(sessionId: string): AbortSignal | undefined {
    return this.sessions.get(sessionId)?.dependencyAbortController.signal;
  }

  beginCleanup(sessionId: string): boolean {
    const state = this.sessions.get(sessionId);
    if (!state || state.isCleanupStarted) return false;
    state.isCleanupStarted = true;
    state.dependencyAbortController.abort();
    return true;
  }

  isCleanupStarted(sessionId: string): boolean {
    return this.sessions.get(sessionId)?.isCleanupStarted ?? false;
  }

  async disposeAssignments(args: { sessionId: string }): Promise<void> {
    const state = this.requireSession(args.sessionId);
    try {
      await this.worktreeManager.cleanupSession(
        args.sessionId,
        state.freshDestinationParent,
      );
    } catch (error) {
      log.warn(`cleanupSession failed for ${args.sessionId}`, error);
    }
    state.workspaceManager.removeOwnedArtifactWorkspaces();
    this.sessions.delete(args.sessionId);
  }

  private requireSession(sessionId: string): SessionWorkspaceState {
    const state = this.sessions.get(sessionId);
    if (!state) {
      throw new Error(`Workspace session ${sessionId} is not open`);
    }
    return state;
  }
}
